CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE SCHEMA IF NOT EXISTS events;
CREATE TABLE IF NOT EXISTS content_items(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),owner_id UUID NOT NULL,content_type TEXT NOT NULL,slug TEXT UNIQUE,title TEXT NOT NULL,summary TEXT,body TEXT NOT NULL,price_cents BIGINT,price_unit TEXT,currency TEXT DEFAULT 'IDR',tags TEXT[],cover_image TEXT,category TEXT,content_status TEXT NOT NULL DEFAULT 'active',rating REAL DEFAULT 0,review_count INT DEFAULT 0,metadata JSONB DEFAULT '{}'::jsonb,published_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_news_content_type_status ON content_items(content_type,content_status,published_at DESC,created_at DESC);
CREATE TABLE IF NOT EXISTS news_editorial_events(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),content_id UUID NOT NULL REFERENCES content_items(id) ON DELETE CASCADE,actor_id UUID NOT NULL,actor_role TEXT NOT NULL DEFAULT 'editor',action TEXT NOT NULL,from_status TEXT,to_status TEXT NOT NULL,note TEXT,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS news_article_versions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),content_id UUID NOT NULL REFERENCES content_items(id) ON DELETE CASCADE,version_number BIGINT NOT NULL,actor_id UUID,actor_role TEXT NOT NULL DEFAULT 'system',action TEXT NOT NULL,editorial_status TEXT,title TEXT NOT NULL,summary TEXT,body TEXT NOT NULL,tags TEXT[],cover_image TEXT,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,content_status TEXT NOT NULL,published_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(content_id,version_number));
CREATE TABLE IF NOT EXISTS news_source_references(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),content_id UUID NOT NULL REFERENCES content_items(id) ON DELETE CASCADE,position INT NOT NULL DEFAULT 0,source_url TEXT NOT NULL,source_domain TEXT,source_kind TEXT NOT NULL DEFAULT 'user_supplied',verification_status TEXT NOT NULL DEFAULT 'unverified',editor_note TEXT,checked_at TIMESTAMPTZ,first_seen_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),last_seen_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(content_id,source_url));
CREATE TABLE IF NOT EXISTS news_source_review_events(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),content_id UUID NOT NULL REFERENCES content_items(id) ON DELETE CASCADE,source_id UUID REFERENCES news_source_references(id) ON DELETE SET NULL,reviewer_id UUID NOT NULL,from_source_kind TEXT NOT NULL,to_source_kind TEXT NOT NULL,from_verification_status TEXT NOT NULL,to_verification_status TEXT NOT NULL,note TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS events.event_log(event_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),event_name TEXT NOT NULL,occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),actor_user_id UUID,anonymous_id TEXT,session_id TEXT,tenant_id TEXT NOT NULL DEFAULT 'default',locale TEXT,source TEXT NOT NULL DEFAULT 'web',page TEXT,entity_type TEXT,entity_id TEXT,properties JSONB NOT NULL DEFAULT '{}'::jsonb,context JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_news_event_log_entity_time ON events.event_log(entity_type,entity_id,occurred_at DESC);
CREATE TABLE IF NOT EXISTS events.event_outbox(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),aggregate_type TEXT NOT NULL,aggregate_id TEXT NOT NULL,event_type TEXT NOT NULL,payload JSONB NOT NULL,routing_key TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',retry_count INT NOT NULL DEFAULT 0,available_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),published_at TIMESTAMPTZ,error_message TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),event_key TEXT UNIQUE);
CREATE INDEX IF NOT EXISTS idx_news_outbox_pending ON events.event_outbox(status,available_at,created_at) WHERE status='pending';